package game.agent.persistence;
import java.nio.file.*;import java.util.*;import game.agent.llm.Json;
/** Restore drill: validates every copied envelope using the same bounded decoder as production. */
public class CheckpointAudit {public static void main(String[] args)throws Exception{int checked=0;try(java.util.stream.Stream<Path> files=Files.list(Path.of(args[0]))){for(Path file:(Iterable<Path>)files::iterator){String name=file.getFileName().toString();if(!name.matches("[a-f0-9]{64}\\.json"))continue;Map<String,Object> value=CheckpointDocument.decode(name.substring(0,64),Files.readAllBytes(file));if(value.get("world") instanceof Map){Map<String,Object> w=Json.asObject(value.get("world"));if(w.containsKey("starterChosen")&&w.containsKey("selected"))game.agent.growth.GrowthWorld.restore(w,()->0,()->UUID.randomUUID().toString());}if(value.containsKey("battle")&&value.get("battle")!=null)game.agent.duel.DuelBattle.restore(Json.asObject(value.get("battle")));checked++;}}System.out.println("Checkpoint envelopes validated: "+checked);}}
